fn main() {
    // Every command granted by a capability file must be listed here:
    // tauri-build generates the allow-/deny- permissions for exactly this
    // list into the gitignored src-tauri/permissions/autogenerated/, and a
    // capability referencing an unlisted command fails the build on a fresh
    // clone (locally it can appear to work off stale generated files).
    tauri_build::try_build(tauri_build::Attributes::new().app_manifest(
        tauri_build::AppManifest::new().commands(&[
            "get_setup_status",
            "list_agents",
            "get_dashboard_status",
            "get_image_status",
            "get_image_build_status",
            "get_agent_sign_in_status",
            "get_network_prune_preview",
            "get_run_status",
            "get_log_snapshot",
            "get_egress_log",
            "get_auth_log",
            "get_auth_status",
            "get_auth_explain",
            "get_why_network",
            "get_why_state",
            "get_why_host",
            "get_why_workspace",
            "get_managed_sessions",
            "get_managed_session_status",
            "get_managed_session_diagnostics",
            "get_managed_session_log_snapshot",
            "get_managed_session_worktree",
            "write_session_input",
            "get_launch_status",
            "stop_run",
            "kill_run",
            "repair_run",
            "stop_managed_session",
            "kill_managed_session",
            "repair_managed_session",
            "cleanup_managed_session",
            "keep_managed_session_worktree",
            "merge_managed_session_worktree",
            "recover_managed_session_worktree",
            "discard_managed_session_worktree",
            "rebuild_agent_image",
            "start_agent_sign_in",
            "prune_managed_networks",
            "plan_run",
            "launch_run",
            "set_attention_badge",
        ]),
    ))
    .expect("failed to build Tauri application manifest");
}
